DROP TABLE IF EXISTS `invoices`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `invoices` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `sequence_number` mediumint unsigned DEFAULT NULL,
  `customer_sequence_number` mediumint unsigned DEFAULT NULL,
  `invoice_date` datetime NOT NULL,
  `due_date` date DEFAULT NULL,
  `invoice_number` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reference_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `paid_status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tax_per_item` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `discount_per_item` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `discount_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `discount` decimal(15,2) DEFAULT NULL,
  `discount_val` bigint DEFAULT NULL,
  `sub_total` bigint NOT NULL,
  `total` bigint NOT NULL,
  `tax` bigint NOT NULL,
  `due_amount` bigint NOT NULL,
  `sent` tinyint(1) NOT NULL DEFAULT '0',
  `viewed` tinyint(1) NOT NULL DEFAULT '0',
  `unique_hash` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `company_id` int unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `creator_id` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `template_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_id` bigint unsigned DEFAULT NULL,
  `recurring_invoice_id` bigint unsigned DEFAULT NULL,
  `exchange_rate` decimal(19,6) DEFAULT NULL,
  `base_discount_val` bigint DEFAULT NULL,
  `base_sub_total` bigint DEFAULT NULL,
  `base_total` bigint DEFAULT NULL,
  `base_tax` bigint DEFAULT NULL,
  `base_due_amount` bigint DEFAULT NULL,
  `currency_id` int unsigned DEFAULT NULL,
  `sales_tax_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sales_tax_address_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `overdue` tinyint(1) NOT NULL DEFAULT '0',
  `tax_included` tinyint(1) NOT NULL DEFAULT '0',
  `amount_debit` decimal(15,2) NOT NULL DEFAULT '0.00',
  `amount_credit` decimal(15,2) NOT NULL DEFAULT '0.00',
  `amount_debit_date` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `amount_credit_date` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lorry_receipt_id` bigint unsigned DEFAULT NULL,
  `date_created` datetime DEFAULT NULL,
  `date_modified` datetime DEFAULT NULL,
  `modified_dates` json DEFAULT NULL,
  `consignee_customer_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `invoices_company_id_foreign` (`company_id`),
  KEY `invoices_customer_id_foreign` (`customer_id`),
  KEY `invoices_recurring_invoice_id_foreign` (`recurring_invoice_id`),
  KEY `invoices_currency_id_foreign` (`currency_id`),
  KEY `idx_invoices_template_company` (`template_name`,`company_id`),
  KEY `idx_invoices_template_company_number` (`template_name`,`company_id`,`invoice_number`),
  KEY `idx_invoices_lorry_receipt_id` (`lorry_receipt_id`),
  KEY `invoices_consignee_customer_id_foreign` (`consignee_customer_id`),
  KEY `invoices_creator_id_idx` (`creator_id`),
  KEY `invoices_updated_by_idx` (`updated_by`),
  CONSTRAINT `invoices_company_id_foreign` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `invoices_consignee_customer_id_foreign` FOREIGN KEY (`consignee_customer_id`) REFERENCES `customers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `invoices_creator_id_foreign` FOREIGN KEY (`creator_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `invoices_currency_id_foreign` FOREIGN KEY (`currency_id`) REFERENCES `currencies` (`id`),
  CONSTRAINT `invoices_customer_id_foreign` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`),
  CONSTRAINT `invoices_lorry_receipt_id_foreign` FOREIGN KEY (`lorry_receipt_id`) REFERENCES `lorry_receipts` (`id`) ON DELETE SET NULL,
  CONSTRAINT `invoices_recurring_invoice_id_foreign` FOREIGN KEY (`recurring_invoice_id`) REFERENCES `recurring_invoices` (`id`),
  CONSTRAINT `invoices_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=471 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
